CREATE DATABASE IF NOT EXISTS complaint_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE complaint_system;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS admin(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,username VARCHAR(50) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaints(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category ENUM('Electricity','Water','Cleaning','Internet','Other') NOT NULL,description VARCHAR(2000) NOT NULL,status ENUM('Pending','In Progress','Resolved') NOT NULL DEFAULT 'Pending',is_escalated TINYINT(1) NOT NULL DEFAULT 0,date_submitted DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,date_resolved DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_complaints_user(user_id),INDEX idx_complaints_status(status,is_escalated,date_submitted),CONSTRAINT fk_complaint_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
